//! The generated files: one crate per segment (a library to deploy it from
//! any program, and a binary that deploys it on its own), and the crossing
//! report.
//!
//! A segment crate depends on gdl, the contract, and the implementation
//! crates of the nodes it hosts, and on nothing else of the graph's: an
//! implementation's native dependencies stay out of every other segment's
//! build.

use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::{Path, PathBuf};

use gdl::{Layout, Manifest, Role};

use crate::Error;
use crate::paths::{display, relative};
use crate::spec::{Contract, GdlDep, Spec};

/// Marks every generated file. `--check` and stale-file cleanup find
/// generated files by it.
pub(crate) const MARKER: &str = "@generated by gdl-gen; do not edit";

/// Everything to write under the output directory, keyed by path relative
/// to it. `out` is the output directory, absolute and normalized.
pub(crate) fn files(
    spec: &Spec,
    contract: &Contract,
    manifest: &Manifest,
    layout: &Layout,
    out: &Path,
) -> Result<BTreeMap<PathBuf, String>, Error> {
    let segments: Vec<&str> = spec.placement.segments().map(|(name, _)| name).collect();
    let spec_dir = crate::dump::absolute(&spec.dir)?;
    let mut files = BTreeMap::new();
    for (segment, nodes) in spec.placement.segments() {
        let crate_dir = out.join(segment);
        let regenerate = regenerate_command(spec, &spec_dir, &crate_dir, out);
        let unit = Unit {
            spec,
            contract,
            manifest,
            segment,
            segments: &segments,
            nodes,
            crate_dir: &crate_dir,
            regenerate: &regenerate,
        };
        files.insert(PathBuf::from(segment).join("Cargo.toml"), unit.cargo_toml());
        files.insert(
            PathBuf::from(segment).join("src/lib.rs"),
            rustfmt(&unit.lib_rs())?,
        );
        files.insert(
            PathBuf::from(segment).join("src/main.rs"),
            rustfmt(&unit.main_rs())?,
        );
    }
    files.insert(
        PathBuf::from("crossings.txt"),
        format!(
            "# {MARKER}\n# What one request of `{}` costs under this placement.\n{}\n",
            manifest.name,
            layout.report()
        ),
    );
    Ok(files)
}

/// Format generated Rust as `cargo fmt` would, so formatting the generated
/// crates is not drift. The text is built line by line; rustfmt owns the
/// layout, rather than a second copy of its rules here.
fn rustfmt(text: &str) -> Result<String, Error> {
    use std::io::Write as _;
    use std::process::{Command, Stdio};

    // rustfmt reads a `rustfmt.toml` from where it runs and above. Run it
    // with a config of its own, so the output does not depend on where the
    // generator is run.
    let config = rustfmt_config()?;
    let rustfmt = std::env::var_os("RUSTFMT").unwrap_or_else(|| "rustfmt".into());
    let mut child = Command::new(rustfmt)
        .args([
            "--edition",
            "2024",
            "--emit",
            "stdout",
            "--quiet",
            "--config-path",
        ])
        .arg(&config)
        .current_dir(config.parent().unwrap_or(&config))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| Error::new(format!("running rustfmt: {e}")))?;
    child
        .stdin
        .take()
        .ok_or_else(|| Error::new("rustfmt has no stdin"))?
        .write_all(text.as_bytes())
        .map_err(|e| Error::new(format!("writing to rustfmt: {e}")))?;
    let output = child
        .wait_with_output()
        .map_err(|e| Error::new(format!("running rustfmt: {e}")))?;
    if !output.status.success() {
        return Err(Error::new(format!(
            "rustfmt rejected generated code (a gdl-gen bug):\n{}\n{text}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    String::from_utf8(output.stdout).map_err(|e| Error::new(format!("rustfmt output: {e}")))
}

/// A directory of this process's own holding the default rustfmt config.
fn rustfmt_config() -> Result<PathBuf, Error> {
    let dir = std::env::temp_dir().join(format!("gdl-gen-rustfmt-{}", std::process::id()));
    std::fs::create_dir_all(&dir).map_err(|e| Error::new(format!("{}: {e}", dir.display())))?;
    let file = dir.join("rustfmt.toml");
    std::fs::write(&file, "edition = \"2024\"\n")
        .map_err(|e| Error::new(format!("{}: {e}", file.display())))?;
    Ok(file)
}

/// The package name of a segment's crate.
pub(crate) fn package(manifest: &Manifest, segment: &str) -> String {
    package_name(&manifest.name, segment)
}

/// The package that graph `graph` generates for `part`: a segment, or the
/// contract.
pub(crate) fn package_name(graph: &str, part: &str) -> String {
    format!("{}-{}", slug(graph), slug(part))
}

fn slug(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect()
}

/// The command that regenerates the output, run from the generated crate's
/// directory.
fn regenerate_command(spec: &Spec, spec_dir: &Path, crate_dir: &Path, out: &Path) -> String {
    let file = spec.file.file_name().unwrap_or_default();
    let spec_file = display(&relative(crate_dir, &spec_dir.join(file)));
    let out = display(&relative(crate_dir, out));
    format!("cargo gdl generate --spec {spec_file} --out {out}")
}

struct Unit<'a> {
    spec: &'a Spec,
    contract: &'a Contract,
    manifest: &'a Manifest,
    segment: &'a str,
    segments: &'a [&'a str],
    nodes: &'a [String],
    crate_dir: &'a Path,
    regenerate: &'a str,
}

/// One hosted node that takes an implementation.
struct Hosted<'a> {
    name: &'a str,
    binding: &'a str,
    package: &'a str,
    ty: &'a str,
}

impl Unit<'_> {
    fn package(&self) -> String {
        package(self.manifest, self.segment)
    }

    fn lib(&self) -> String {
        self.package().replace('-', "_")
    }

    /// Hosted nodes that take a binding, in declaration order; validation
    /// guarantees each has one, and an implementation.
    fn hosted(&self) -> Vec<Hosted<'_>> {
        self.manifest
            .nodes
            .iter()
            .filter(|node| node.role != Role::Source && self.nodes.contains(&node.name))
            .map(|node| {
                let bind = &self.spec.bind[&node.name];
                Hosted {
                    name: &node.name,
                    binding: node.binding.as_deref().unwrap_or_default(),
                    package: &bind.package,
                    // `::crate::Type` and `crate::Type` are one path; the
                    // emitted code adds the root itself.
                    ty: bind.ty.trim().trim_start_matches("::"),
                }
            })
            .collect()
    }

    fn hosts_source(&self) -> bool {
        self.manifest
            .nodes
            .iter()
            .any(|node| node.role == Role::Source && self.nodes.contains(&node.name))
    }

    /// Whether the binary can serve the source over JSON lines: both of the
    /// source's types must be serde types, and its request one value. One
    /// line cannot carry a streamed request.
    fn serves(&self) -> bool {
        let Some(hop) = self.manifest.hops.first() else {
            return false;
        };
        let req = hop
            .forward_types
            .first()
            .is_some_and(|t| t.wire && t.stream.is_none());
        let item = hop.backward_types.last().is_some_and(|t| t.wire);
        self.hosts_source() && req && item
    }

    /// Whether the source takes a streamed request.
    fn streamed_source(&self) -> bool {
        self.manifest
            .hops
            .first()
            .and_then(|hop| hop.forward_types.first())
            .is_some_and(|t| t.stream.is_some())
    }

    fn path_to(&self, target: &Path) -> String {
        let target = crate::dump::absolute(target).unwrap_or_else(|_| target.to_path_buf());
        crate::dump::toml_string(&display(&relative(self.crate_dir, &target)))
    }

    fn cargo_toml(&self) -> String {
        let package = self.package();
        let mut text = String::new();
        let _ = writeln!(text, "# {MARKER}.");
        let _ = writeln!(text, "# Regenerate with: {}", self.regenerate);
        let _ = writeln!(text);
        let _ = writeln!(text, "[package]");
        let _ = writeln!(text, "name = \"{package}\"");
        let _ = writeln!(text, "version = \"0.0.0\"");
        let _ = writeln!(text, "edition = \"2024\"");
        let _ = writeln!(text, "publish = false");
        let _ = writeln!(text);
        let _ = writeln!(text, "[lib]");
        let _ = writeln!(text, "path = \"src/lib.rs\"");
        let _ = writeln!(text);
        let _ = writeln!(text, "[[bin]]");
        let _ = writeln!(text, "name = \"{package}\"");
        let _ = writeln!(text, "path = \"src/main.rs\"");
        let _ = writeln!(text);
        let _ = writeln!(text, "[dependencies]");
        let source = match &self.spec.gdl {
            GdlDep::Path(path) => format!("path = {}", self.path_to(path)),
            GdlDep::Version(version) => format!("version = {}", crate::dump::toml_string(version)),
        };
        let gdl = if self.serves() {
            format!("{{ {source}, features = [\"json-lines\"] }}")
        } else {
            format!("{{ {source} }}")
        };
        let _ = writeln!(text, "gdl = {gdl}");
        let _ = writeln!(
            text,
            "{} = {{ path = {} }}",
            self.contract.package,
            self.path_to(&self.contract.path)
        );
        // Each implementation crate once, however many nodes it implements.
        let mut implementations: BTreeMap<&str, &Path> = BTreeMap::new();
        for node in self.hosted() {
            implementations.insert(node.package, &self.spec.bind[node.name].path);
        }
        for (package, path) in implementations {
            let _ = writeln!(text, "{package} = {{ path = {} }}", self.path_to(path));
        }
        let _ = writeln!(
            text,
            "serde = {{ version = \"1\", features = [\"derive\"] }}"
        );
        let _ = writeln!(
            text,
            "tokio = {{ version = \"1\", features = [\"io-std\", \"io-util\", \"macros\", \"rt-multi-thread\", \"signal\"] }}"
        );
        let _ = writeln!(text, "toml = \"0.9\"");
        text
    }

    fn lib_rs(&self) -> String {
        let hosted = self.hosted();
        let mut text = String::new();
        let _ = writeln!(text, "// {MARKER}.");
        let _ = writeln!(text, "// Regenerate with: {}", self.regenerate);
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "//! Segment `{}` of graph `{}`, hosting {}.",
            self.segment,
            self.manifest.name,
            list(self.nodes)
        );
        let _ = writeln!(text, "//!");
        let _ = writeln!(
            text,
            "//! [`start`] deploys it inside a program; the `{}` binary deploys it on",
            self.package()
        );
        let _ = writeln!(text, "//! its own.");
        let _ = writeln!(text);
        let _ = writeln!(text, "use std::sync::Arc;");
        let _ = writeln!(text);
        // Paths from the crate root (`::`), here and for every
        // implementation: a hosted crate called `contract` must not be
        // shadowed by this alias.
        let _ = writeln!(
            text,
            "pub use ::{} as contract;",
            self.contract.module.trim().trim_start_matches("::")
        );
        let _ = writeln!(text);
        let _ = writeln!(text, "/// This segment's name in the placement.");
        let _ = writeln!(text, "pub const SEGMENT: &str = \"{}\";", self.segment);
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "/// Every segment of the placement: an instance waits for all of them."
        );
        let quoted: Vec<String> = self.segments.iter().map(|s| format!("\"{s}\"")).collect();
        let _ = writeln!(
            text,
            "pub const SEGMENTS: &[&str] = &[{}];",
            quoted.join(", ")
        );
        let _ = writeln!(text);
        let _ = writeln!(text, "/// The placement this crate was generated for.");
        let placement = toml::to_string(&self.spec.placement).unwrap_or_default();
        let _ = writeln!(
            text,
            "pub const PLACEMENT: &str = {};",
            raw_string(&placement)
        );
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "/// The implementations of the nodes this segment hosts."
        );
        if hosted.is_empty() {
            let _ = writeln!(text, "pub struct Nodes {{}}");
        } else {
            let _ = writeln!(text, "pub struct Nodes {{");
            for node in &hosted {
                let _ = writeln!(text, "    /// Node `{}`.", node.name);
                let _ = writeln!(text, "    pub {}: ::{},", node.binding, node.ty);
            }
            let _ = writeln!(text, "}}");
        }
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "/// Deploy this segment on `node`. Every segment's instances must be in"
        );
        let _ = writeln!(text, "/// `roster`.");
        let _ = writeln!(text, "pub fn start(");
        let _ = writeln!(text, "    node: Arc<gdl::velo::Velo>,");
        let _ = writeln!(text, "    roster: &gdl::Roster,");
        let _ = writeln!(text, "    config: gdl::RuntimeConfig,");
        let _ = writeln!(text, "    nodes: Nodes,");
        let _ = writeln!(text, ") -> gdl::Result<");
        let _ = writeln!(
            text,
            "    gdl::Segment<impl gdl::Next<contract::SourceReq, contract::SourceItem> + gdl::Register + use<>>,"
        );
        let _ = writeln!(text, "> {{");
        let _ = writeln!(
            text,
            "    let placement = gdl::Placement::from_toml(PLACEMENT)?;"
        );
        let _ = writeln!(text, "    let manifest = contract::manifest();");
        let _ = writeln!(
            text,
            "    let deployment = gdl::Deployment::new(node, &manifest, &placement, SEGMENT, roster, config)?;"
        );
        let mut bindings = String::from("contract::Bindings::new()");
        for node in &hosted {
            let _ = write!(bindings, ".{0}(nodes.{0})", node.binding);
        }
        if hosted.is_empty() {
            let _ = writeln!(text, "    let Nodes {{}} = nodes;");
        }
        let _ = writeln!(
            text,
            "    let root = contract::assemble(&deployment, {bindings})?;"
        );
        let _ = writeln!(text, "    deployment.start(root)");
        let _ = writeln!(text, "}}");
        text
    }

    fn main_rs(&self) -> String {
        let hosted = self.hosted();
        let package = self.package();
        let lib = self.lib();
        let serves = self.serves();
        let mut text = String::new();
        let _ = writeln!(text, "// {MARKER}.");
        let _ = writeln!(text, "// Regenerate with: {}", self.regenerate);
        let _ = writeln!(text);
        let _ = writeln!(text, "//! Runs segment `{}` on its own.", self.segment);
        let _ = writeln!(text, "//!");
        let _ = writeln!(
            text,
            "//! Usage: `{package} <config.toml>`, where the config is:"
        );
        let _ = writeln!(text, "//!");
        let mut rows = vec![
            (
                "listen = \"127.0.0.1:0\"".to_string(),
                "this instance's address".to_string(),
            ),
            (
                "roster = \"/run/roster\"".to_string(),
                "fresh for each deployment, shared by every instance".to_string(),
            ),
            ("rendezvous_ms = 30000".to_string(), "optional".to_string()),
            (
                "[instances]".to_string(),
                "optional: instances per segment, 1 by default".to_string(),
            ),
            (
                "[runtime]".to_string(),
                "optional: gdl::RuntimeConfig".to_string(),
            ),
        ];
        for node in &hosted {
            rows.push((
                format!("[node.{}]", node.name),
                format!("optional: {}'s Build::Config", node.name),
            ));
        }
        let width = rows.iter().map(|(key, _)| key.len()).max().unwrap_or(0);
        let _ = writeln!(text, "//! ```toml");
        for (key, comment) in rows {
            let _ = writeln!(text, "//! {key:<width$}  # {comment}");
        }
        let _ = writeln!(text, "//! ```");
        if serves {
            let _ = writeln!(text, "//!");
            let _ = writeln!(
                text,
                "//! This segment hosts the source. Once every segment is ready, it reads"
            );
            let _ = writeln!(
                text,
                "//! one JSON request per line on stdin and answers each with one line per"
            );
            let _ = writeln!(
                text,
                "//! item, `{{\"item\": ...}}`, then `{{\"done\": null}}` or `{{\"error\": \"...\"}}`."
            );
        } else if self.hosts_source() && self.streamed_source() {
            let _ = writeln!(text, "//!");
            let _ = writeln!(
                text,
                "//! This segment hosts the source, which takes a streamed request. One JSON"
            );
            let _ = writeln!(
                text,
                "//! line cannot carry it, so the binary only serves; call it through the library."
            );
        } else if self.hosts_source() {
            let _ = writeln!(text, "//!");
            let _ = writeln!(
                text,
                "//! This segment hosts the source, but the source's types are not serde"
            );
            let _ = writeln!(
                text,
                "//! types, so the binary only serves; call it through the library."
            );
        }
        let _ = writeln!(text);
        let _ = writeln!(text, "use std::sync::Arc;");
        let _ = writeln!(text, "use std::time::Duration;");
        let _ = writeln!(text);
        let _ = writeln!(text, "use {lib}::{{Nodes, SEGMENT, SEGMENTS, start}};");
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "type Failure = Box<dyn std::error::Error + Send + Sync>;"
        );
        let _ = writeln!(text);
        let _ = writeln!(text, "#[derive(serde::Deserialize)]");
        let _ = writeln!(text, "#[serde(deny_unknown_fields)]");
        let _ = writeln!(text, "struct Config {{");
        let _ = writeln!(text, "    listen: std::net::SocketAddr,");
        let _ = writeln!(text, "    roster: std::path::PathBuf,");
        let _ = writeln!(text, "    #[serde(default = \"rendezvous_ms\")]");
        let _ = writeln!(text, "    rendezvous_ms: u64,");
        let _ = writeln!(text, "    #[serde(default)]");
        let _ = writeln!(
            text,
            "    instances: std::collections::BTreeMap<String, usize>,"
        );
        let _ = writeln!(text, "    #[serde(default)]");
        let _ = writeln!(text, "    runtime: gdl::RuntimeConfig,");
        let _ = writeln!(text, "    #[serde(default)]");
        let _ = writeln!(text, "    node: NodeConfigs,");
        let _ = writeln!(text, "}}");
        let _ = writeln!(text);
        let _ = writeln!(text, "fn rendezvous_ms() -> u64 {{");
        let _ = writeln!(text, "    30_000");
        let _ = writeln!(text, "}}");
        let _ = writeln!(text);
        let _ = writeln!(text, "#[derive(Default, serde::Deserialize)]");
        let _ = writeln!(text, "#[serde(deny_unknown_fields)]");
        if hosted.is_empty() {
            let _ = writeln!(text, "struct NodeConfigs {{}}");
        } else {
            let _ = writeln!(text, "struct NodeConfigs {{");
            for node in &hosted {
                let _ = writeln!(text, "    #[serde(rename = \"{}\", default)]", node.name);
                let _ = writeln!(text, "    {}: Option<toml::Table>,", node.binding);
            }
            let _ = writeln!(text, "}}");
        }
        let _ = writeln!(text);
        let _ = writeln!(text, "#[tokio::main]");
        let _ = writeln!(text, "async fn main() -> std::process::ExitCode {{");
        let _ = writeln!(text, "    match run().await {{");
        let _ = writeln!(text, "        Ok(()) => std::process::ExitCode::SUCCESS,");
        let _ = writeln!(text, "        Err(error) => {{");
        let _ = writeln!(text, "            eprintln!(\"{{SEGMENT}}: {{error}}\");");
        let _ = writeln!(text, "            std::process::ExitCode::FAILURE");
        let _ = writeln!(text, "        }}");
        let _ = writeln!(text, "    }}");
        let _ = writeln!(text, "}}");
        let _ = writeln!(text);
        let _ = writeln!(text, "async fn run() -> Result<(), Failure> {{");
        let _ = writeln!(text, "    let path = std::env::args_os()");
        let _ = writeln!(text, "        .nth(1)");
        let _ = writeln!(text, "        .ok_or(\"usage: {package} <config.toml>\")?;");
        let _ = writeln!(
            text,
            "    let config: Config = toml::from_str(&std::fs::read_to_string(&path)?)?;"
        );
        if hosted.is_empty() {
            let _ = writeln!(text, "    let NodeConfigs {{}} = config.node;");
            let _ = writeln!(text, "    let nodes = Nodes {{}};");
        } else {
            let _ = writeln!(text, "    let nodes = Nodes {{");
            for node in &hosted {
                let _ = writeln!(
                    text,
                    "        {}: build::<::{}>(\"{}\", config.node.{}).await?,",
                    node.binding, node.ty, node.name, node.binding
                );
            }
            let _ = writeln!(text, "    }};");
        }
        let _ = writeln!(text, "    let node = gdl::bind_node(config.listen).await?;");
        let _ = writeln!(
            text,
            "    let wait = Duration::from_millis(config.rendezvous_ms);"
        );
        let _ = writeln!(
            text,
            "    if let Some(unknown) = config.instances.keys().find(|s| !SEGMENTS.contains(&s.as_str())) {{"
        );
        let _ = writeln!(
            text,
            "        return Err(format!(\"[instances]: no segment `{{unknown}}`\").into());"
        );
        let _ = writeln!(text, "    }}");
        let _ = writeln!(text, "    // Every instance waits for the same membership.");
        let _ = writeln!(
            text,
            "    let expect = SEGMENTS.iter().map(|s| (*s, config.instances.get(*s).copied().unwrap_or(1)));"
        );
        let _ = writeln!(
            text,
            "    let roster = gdl::Roster::rendezvous(&config.roster, SEGMENT, &node, expect, wait).await?;"
        );
        let _ = writeln!(
            text,
            "    let segment = start(Arc::clone(&node), &roster, config.runtime, nodes)?;"
        );
        let _ = writeln!(
            text,
            "    // No request may leave before every instance it can be routed to"
        );
        let _ = writeln!(text, "    // has registered its handlers.");
        let _ = writeln!(
            text,
            "    roster.ready(&config.roster.join(\"ready\"), SEGMENT, &node, wait).await?;"
        );
        let _ = writeln!(text, "    eprintln!(\"{{SEGMENT}}: ready\");");
        if serves {
            let _ = writeln!(
                text,
                "    let input = tokio::io::BufReader::new(tokio::io::stdin());"
            );
            let _ = writeln!(
                text,
                "    let call = |request: {lib}::contract::SourceReq| segment.call::<_, {lib}::contract::SourceItem>(gdl::Cx::new(), request);"
            );
            let _ = writeln!(
                text,
                "    gdl::serve_json_lines(input, tokio::io::stdout(), call).await?;"
            );
            let _ = writeln!(text, "    Ok(())");
        } else {
            let _ = writeln!(text, "    tokio::signal::ctrl_c().await?;");
            let _ = writeln!(text, "    drop(segment);");
            let _ = writeln!(text, "    Ok(())");
        }
        let _ = writeln!(text, "}}");
        if !hosted.is_empty() {
            let _ = writeln!(text);
            let _ = writeln!(text, "/// Build one implementation from its config table.");
            let _ = writeln!(
                text,
                "async fn build<T: gdl::Build>(node: &str, config: Option<toml::Table>) -> Result<T, Failure> {{"
            );
            let _ = writeln!(
                text,
                "    let config: T::Config = toml::Value::Table(config.unwrap_or_default())"
            );
            let _ = writeln!(text, "        .try_into()");
            let _ = writeln!(
                text,
                "        .map_err(|e| format!(\"[node.{{node}}]: {{e}}\"))?;"
            );
            let _ = writeln!(text, "    T::build(config)");
            let _ = writeln!(text, "        .await");
            let _ = writeln!(
                text,
                "        .map_err(|e| format!(\"building {{node}}: {{e}}\").into())"
            );
            let _ = writeln!(text, "}}");
        }
        text
    }
}

fn list(nodes: &[String]) -> String {
    let quoted: Vec<String> = nodes.iter().map(|n| format!("`{n}`")).collect();
    quoted.join(", ")
}

/// A Rust raw string literal holding `text`, with enough `#`s.
fn raw_string(text: &str) -> String {
    let mut hashes = 1;
    while text.contains(&format!("\"{}", "#".repeat(hashes))) {
        hashes += 1;
    }
    let h = "#".repeat(hashes);
    format!("r{h}\"{text}\"{h}")
}
